import { flowSpecToManifest } from './flowspec.js';
function canonical(value) {
    if (Array.isArray(value))
        return value.map(canonical);
    if (value && typeof value === 'object') {
        return Object.fromEntries(Object.entries(value)
            .filter(([, item]) => item !== undefined)
            .sort(([left], [right]) => left.localeCompare(right))
            .map(([key, item]) => [key, canonical(item)]));
    }
    return value;
}
export function canonicalApplicationBytes(value) {
    return new TextEncoder().encode(JSON.stringify(canonical(value)));
}
async function hash(value) {
    const bytes = canonicalApplicationBytes(value);
    const digest = await crypto.subtle.digest('SHA-256', bytes.slice().buffer);
    return `sha256:${Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('')}`;
}
/**
 * Compile the developer-authored Flow definition into the one contract used by
 * local runtimes, remote services, Studio, publishing, and SDK introspection.
 */
export async function compileApplicationContract(spec, tenantId, applicationId) {
    if (spec.version !== 1)
        throw new Error(`Unsupported flow_version ${spec.version}; this SDK supports flow_version 1`);
    const manifest = flowSpecToManifest(spec, tenantId, applicationId);
    const [model, authorization, workflows, agents, capabilities, modules] = await Promise.all([
        hash({ collections: manifest.collections, indexes: manifest.indexes, references: manifest.references }),
        hash(manifest.policies),
        hash({ workflows: manifest.workflows, triggers: manifest.triggers, schedules: manifest.schedules }),
        hash(manifest.agents),
        hash(manifest.capabilities),
        hash(manifest.modules ?? []),
    ]);
    const application = await hash({ dsl_version: spec.version, manifest });
    return {
        application_id: applicationId,
        tenant_id: tenantId,
        schema_version: manifest.schema,
        dsl_version: spec.version,
        manifest,
        hashes: { model, authorization, workflows, agents, capabilities, modules, application },
    };
}
